<script id="vertexShader" type="x-shader/x-vertex">
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;

    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat4 uNormalMatrix;

    varying vec3 vNormal;
    varying vec3 vPosition;
    varying vec2 vTexCoord;

    void main() {
        vNormal = (uNormalMatrix * vec4(aNormal, 0.0)).xyz;
        vPosition = (uModelViewMatrix * vec4(aPosition, 1.0)).xyz;
        vTexCoord = aTexCoord;
        gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);
    }
</script>

<script id="fragmentShader" type="x-shader/x-fragment">
    precision mediump float;

    varying vec3 vNormal;
    varying vec3 vPosition;
    varying vec2 vTexCoord;

    uniform vec3 uColor;
    uniform float uShininess;
    uniform vec3 uLightPos;
    uniform sampler2D uTexture;

    void main() {
        vec3 norm = normalize(vNormal);
        vec3 lightDir = normalize(uLightPos - vPosition);

        // Diffuse
        float diff = max(dot(norm, lightDir), 0.0);

        // Specular (Blinn-Phong)
        vec3 viewDir = normalize(-vPosition);
        vec3 halfwayDir = normalize(lightDir + viewDir);
        float spec = pow(max(dot(norm, halfwayDir), 0.0), uShininess);

        vec4 texColor = texture2D(uTexture, vTexCoord);

        // Ambient component based on color
        vec3 ambient = uColor * 0.2;
        vec3 diffuse = diff * uColor;
        vec3 specular = vec3(1.0) * spec * (uColor * 0.5 + 0.5);

        vec3 finalColor = ambient + diffuse + specular;
        gl_FragColor = vec4(finalColor, 1.0) * texColor;
    }
</script>

<script>
    const canvas = document.getElementById('coin-hero');
    const gl = canvas.getContext('webgl', { antialias: true });

