    // --- Geometry Generation ---
    function createCoinGeometry() {
        const vertices = [];
        const normals = [];
        const texCoords = [];
        const thickness = 0.2;
        const radius = 1.0;
        const segments = 64;

        // Faces and Edge
        for (let i = 0; i <= segments; i++) {
            const theta = (i / segments) * Math.PI * 2;
            const x = Math.cos(theta);
            const z = Math.sin(theta);

            // Front Face
