            normals.push(x, 0.1, z);
            texCoords.push(0.5 + (x * 0.5), 0.5 + (z * 0.5));

            // Back Face
            vertices.push(x, -0.1, z);
            normals.push(-x, -0.1, -z);
            texCoords.push(0.5 + (x * 0.5), 0.5 + (z * 0.5));

            // Edge Vertices
            vertices.push(x, 0, z);
            normals.push(x, 1.0, z); // simplified normal for edge
            texCoords.push(0.5 + (x * 0.5), 0.5 + (z * 0.5));

            vertices.push(x, -thickness, z);
            normals.push(x, -1.0, z);
            texCoords.push(0.5 + (x * 0.5), 0.5 + (z * 0.5));
        }

        // Indices for Front Face
        for (let i = 0; i < segments; i++) {
            const next = (i + 1) % segments;
            vertices.push(Math.cos((i/segments)*Math.PI*2), 0.1, Math.sin((i/segments)*Math.PI*2));
            vertices.push(Math.cos(((i+1)/segments)*Math.PI*2), 0.1, Math.sin(((i+1)/segments)*Math.PI*2));
            vertices.push(Math.cos(((i+2)/segments)*Math.PI*2), 0.1, Math.sin(((i+2)/segments)*Math.PI*2));
        }

        // To simplify for this prompt's strict requirements and self-containment:
        // We will construct a proper Cylinder geometry (Disk + Edge segments) manually.
        const coinVerts = [];
        const coinNorms = [];
        const coinTexs = [];

        // Front Disc
        for(let i=0; i<=segments; i++) {
            let a = (i/segments)*Math.PI*2;
            coinVerts.push(Math.cos(a), 0.1, Math.sin(a));
            coinNorms.push(Math.cos(a), 0.1, Math.sin(a));
            coinTexs.push(0.5 + Math.cos(a)*0.5, 0.5 + Math.sin(a)*0.5);
        }
        for(let i=0; i<segments; i++) {
            let j = (i+1)%segments;
            coinVerts.push(Math.cos((i/segments)*Math.PI*2), 0.1, Math.sin((i/segments)*Math.PI*2));
            coinVerts.push(Math.cos((j/segments)*Math.PI*2), 0.1, Math.sin((j/segments)*Math.PI*2));
            coinVerts.push(Math.cos(((i+1)/segments)*Math.PI*2), 0.1, Math.sin(((i+1)/segments)*Math.PI*2));
        }

        // Back Disc
        for(let i=0; i<=segments; i++) {
            let a = (i/segments)*Math.PI*2;
            coinVerts.push(Math.cos(a), -0.1, Math.sin(a));
            coinNorms.push(-Math.cos(a), -0.1, -Math.sin(a));
            coinTexs.push(0.5 + Math.cos(a)*0.5, 0.5 + Math.sin(a)*0.5);
        }
        for(let i=0; i<segments; i++) {
            let j = (i+1)%segments;
            coinVerts.push(Math.cos((i/segments)*Math.PI*2), -0.1, Math.sin((i/segments)*Math.PI*2));
            coinVerts.push(Math.cos((j/segments)*Math.PI*2), -0.1, Math.sin((j/segments)*Math.PI*2));
            coinVerts.push(Math.cos(((i+1)/segments)*Math.PI*2), -0.1, Math.sin(((i+1)/segments)*Math.PI*2));
        }

        // Edge segments (Reeding)
        for(let i=0; i<segments; i++) {
            let a1 = (i/segments)*Math.PI*2;
            let a2 = ((i+1)/segments)*Math.PI*2;

            coinVerts.push(Math.cos(a1), 0.1, Math.sin(a1));
            coinVerts.push(Math.cos(a1), -0.1, Math.sin(a1));
            coinVerts.push(Math.cos(a2), 0.1, Math.sin(a2));

            coinVerts.push(Math.cos(a1), -0.1, Math.sin(a1));
            coinVerts.push(Math.cos(a2), -0.1, Math.sin(a2));
            coinVerts.push(Math.cos(a2), 0.1, Math.sin(a2));

            // Normals for edge
            coinNorms.push(Math.cos(a1), 1.0, Math.sin(a1));
            coinNorms.push(Math.cos(a1), -1.0, Math.sin(a1));
            coinNorms.push(Math.cos(a2), 1.0, Math.sin(a2));

            coinNorms.push(Math.cos(a1), -1.0, Math.sin(a1));
            coinNorms.push(Math.cos(a2), -1.0, Math.sin(a2));
            coinNorms.push(Math.cos(a2), 1.0, Math.sin(a2));

            // Tex coords (roughly)
            coinTexs.push(0.5+Math.cos(a1)*0.5, 0.5+Math.sin(a1)*0.5);
            coinTexs.push(0.5+Math.cos(a1)*0.5, 0.5+Math.sin(a1)*0.5);
            coinTexs.push(0.5+Math.cos(a2)*0.5, 0.5+Math.sin(a2)*0.5);

            coinTexs.push(0.5+Math.cos(a1)*0.5, 0.5+Math.sin(a1)*0.5);
            coinTexs.push(0.5+Math.cos(a2)*0.5, 0.5+Math.sin(a2)*0.5);
            coinTexs.push(0.5+Math.cos(a2)*0.5, 0.5+Math.sin(a2)*0.5);
        }

        const vBuffer = gl.createBuffer();
        gl.bindBuffer(gl.ARRAY_BUFFER, vBuffer);
        gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(coinVerts), gl.STATIC_DRAW);

        const nBuffer = gl.createBuffer();
        gl.bindBuffer(gl.ARRAY_BUFFER, nBuffer);
        gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(coinNorms), gl.STATIC_DRAW);

        const tBuffer = gl.createBuffer();
        gl.bindBuffer(gl.ARRAY_BUFFER, tBuffer);
        gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(coinTexs), gl.STATIC_DRAW);

        return { vBuffer, nBuffer, tBuffer, count: coinVerts.length / 3 };
    }

    // --- Texture Generation (Offscreen Canvas) ---
    function createCoinTexture() {
        const texCanvas = document.createElement('canvas');
        texCanvas.width = 512;
        texCanvas.height = 512;
        const ctx = texCanvas.getContext('2d');

        // Background
        ctx.fillStyle = '#444';
