    // --- Grid Coin Rendering (Procedural) ---
    function renderGridCoins() {
        const editions = document.querySelectorAll('.edition');
        editions.forEach(el => {
            const canvasEl = el.querySelector('.edition-canvas');
            const ctx = canvasEl.getContext('2d');
