            ctx.fillText('W', centerX, centerY + 30);

            // Draw Edge Reeding (small lines)
            ctx.strokeStyle = 'rgba(0,0,0,0.2)';
            for(let i=0; i<36; i++) {
                const a = (i/36)*Math.PI*2;
                ctx.beginPath();
                ctx.moveTo(centerX + Math.cos(a)*radius, centerY + Math.sin(a)*radius);
                ctx.lineTo(centerX + Math.cos(a)*(radius+5), centerY + Math.sin(a)*(radius+5));
                ctx.stroke();
            }
        });
    }

    // Init grid coins
    window.onload = () => {
        const c = document.querySelectorAll('.edition-canvas');
        c.forEach(canv => {
            canv.width = 200;
            canv.height = 200;
        });
        renderGridCoins();
    };
</script>

